// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }

    function testFuzz_property(address initialOwner, address newOwner) public {
        vm.assume(initialOwner != address(0));
        vm.assume(newOwner != address(0));

        address observedOwner = c.owner();

        vm.prank(observedOwner);
        bool ok1;
        try c.transferOwnership(initialOwner) {
            ok1 = true;
        } catch {
            ok1 = false;
        }

        address currentOwner = c.owner();

        vm.prank(currentOwner);
        bool ok2;
        try c.transferOwnership(newOwner) {
            ok2 = true;
        } catch {
            ok2 = false;
        }

        assertTrue(!ok2 || (c.owner() == newOwner));
    }
}
